package com.manishrawat.realestate.servlet; import com.manishrawat.realestate.dao.ApplicationDAO; import com.manishrawat.realestate.model.User; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.*; @WebServlet("/application") public class ApplicationServlet extends HttpServlet{private final ApplicationDAO dao=new ApplicationDAO();protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{User u=(User)r.getSession().getAttribute("user");r.setAttribute("applications",dao.all());if("TENANT".equals(u.getRole()))r.setAttribute("applications",dao.forTenant(u.getId()));r.getRequestDispatcher("/WEB-INF/views/applications.jsp").forward(r,s);}catch(Exception e){throw new ServletException(e);}}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{try{User u=(User)r.getSession().getAttribute("user");String action=r.getParameter("action");if("apply".equals(action))dao.apply(Integer.parseInt(r.getParameter("propertyId")),u.getId(),r.getParameter("message"));else dao.status(Integer.parseInt(r.getParameter("id")),r.getParameter("status"));s.sendRedirect("application");}catch(Exception e){throw new IOException(e);}}}
